<?php

namespace MongoDB\Driver\Monitoring;

/**
 * <div id="class.mongodb-driver-monitoring-commandsubscriber" class="reference"> <h1 class="title">The MongoDB\Driver\Monitoring\CommandSubscriber interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.3.0)</p>  <div class="section" id="mongodb-driver-monitoring-commandsubscriber.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Classes may implement this interface to register an event subscriber that is    notified for each started, successful, and failed command event. See    <a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a> for additional information.   </p>  </div>  <div class="section" id="mongodb-driver-monitoring-commandsubscriber.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\Monitoring\CommandSubscriber</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="interfacename">MongoDB\Driver\Monitoring\Subscriber</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-commandsubscriber.commandfailed.php" class="methodname" style="color:#CC7832">commandFailed</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandfailedevent.php" class="type MongoDB\Driver\Monitoring\CommandFailedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandFailedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-commandsubscriber.commandstarted.php" class="methodname" style="color:#CC7832">commandStarted</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandstartedevent.php" class="type MongoDB\Driver\Monitoring\CommandStartedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandStartedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-commandsubscriber.commandsucceeded.php" class="methodname" style="color:#CC7832">commandSucceeded</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsucceededevent.php" class="type MongoDB\Driver\Monitoring\CommandSucceededEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandSucceededEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>             <tr>        <td>PECL mongodb 1.15.0</td>        <td>         在 PHP 8.0 及更高版本中，方法的返回类型被声明为暂定（tentative），         这会导致在实现该接口但未声明相应返回类型的代码中触发弃用提示。         可以添加 <span class="code">#[ReturnTypeWillChange]</span> 属性来消除该弃用提示。        </td>       </tr>     </tbody>       </table>  </div> </div>   <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Monitoring\CommandSubscriber::commandFailed} — Notification method for a failed command</li><li>{@link MongoDB\Driver\Monitoring\CommandSubscriber::commandStarted} — Notification method for a started command</li><li>{@link MongoDB\Driver\Monitoring\CommandSubscriber::commandSucceeded} — Notification method for a successful command</li></ul></div>
 * 
 * Classes may implement this interface to register an event subscriber that is notified for each started, successful, and failed command event.
 * @see https://secure.php.net/manual/en/mongodb.tutorial.apm.php
 * @link https://secure.php.net/manual/en/class.mongodb-driver-monitoring-commandsubscriber.php
 * @since 1.3.0
 */
interface CommandSubscriber extends Subscriber
{
    /**
 * <div id="mongodb-driver-monitoring-commandsubscriber.commandfailed" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandFailed</h1>  <p class="verinfo">(mongodb &gt;=1.3.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandFailed</span> — <span class="dc-title">Notification method for a failed command</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandfailed-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\CommandSubscriber::commandFailed</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandfailedevent.php" class="type MongoDB\Driver\Monitoring\CommandFailedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandFailedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when a command fails.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandfailed-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandfailedevent.php" class="type MongoDB\Driver\Monitoring\CommandFailedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandFailedEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the failed command.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandfailed-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandfailed-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandfailed-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandfailedevent.php" class="classname">MongoDB\Driver\Monitoring\CommandFailedEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>   <li><a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a></li>  </ul> </div></div>
 * 
     * Notification method for a failed command.
     * If the subscriber has been registered with MongoDB\Driver\Monitoring\addSubscriber(), the driver will call this method when a command has failed.
     * @link https://secure.php.net/manual/en/mongodb-driver-monitoring-commandsubscriber.commandfailed.php
     * @param CommandFailedEvent $event An event object encapsulating information about the failed command.
     * @return void
     * @throws \InvalidArgumentException on argument parsing errors.
     * @since 1.3.0
     */
    public function commandFailed(CommandFailedEvent $event): void;

    /**
 * <div id="mongodb-driver-monitoring-commandsubscriber.commandstarted" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandStarted</h1>  <p class="verinfo">(mongodb &gt;=1.3.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandStarted</span> — <span class="dc-title">Notification method for a started command</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandstarted-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\CommandSubscriber::commandStarted</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandstartedevent.php" class="type MongoDB\Driver\Monitoring\CommandStartedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandStartedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when a command is sent   to the server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandstarted-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandstartedevent.php" class="type MongoDB\Driver\Monitoring\CommandStartedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandStartedEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the started command.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandstarted-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandstarted-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandstarted-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandstartedevent.php" class="classname">MongoDB\Driver\Monitoring\CommandStartedEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>   <li><a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a></li>  </ul> </div></div>
 * 
     * Notification method for a started command.
     * If the subscriber has been registered with MongoDB\Driver\Monitoring\addSubscriber(), the driver will call this method when a command has started.
     * @link https://secure.php.net/manual/en/mongodb-driver-monitoring-commandsubscriber.commandstarted.php
     * @param CommandStartedEvent $event An event object encapsulating information about the started command.
     * @return void
     * @throws \InvalidArgumentException on argument parsing errors.
     * @since 1.3.0
     */
    public function commandStarted(CommandStartedEvent $event): void;

    /**
 * <div id="mongodb-driver-monitoring-commandsubscriber.commandsucceeded" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandSucceeded</h1>  <p class="verinfo">(mongodb &gt;=1.3.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\CommandSubscriber::commandSucceeded</span> — <span class="dc-title">Notification method for a successful command</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandsucceeded-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\CommandSubscriber::commandSucceeded</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsucceededevent.php" class="type MongoDB\Driver\Monitoring\CommandSucceededEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandSucceededEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when a command   succeeds.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandsucceeded-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsucceededevent.php" class="type MongoDB\Driver\Monitoring\CommandSucceededEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\CommandSucceededEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the successful command.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandsucceeded-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandsucceeded-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-commandsubscriber.commandsucceeded-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsucceededevent.php" class="classname">MongoDB\Driver\Monitoring\CommandSucceededEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>   <li><a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a></li>  </ul> </div></div>
 * 
     * Notification method for a successful command.
     * If the subscriber has been registered with MongoDB\Driver\Monitoring\addSubscriber(), the driver will call this method when a command has succeeded.
     * @link https://secure.php.net/manual/en/mongodb-driver-monitoring-commandsubscriber.commandsucceeded.php
     * @param CommandSucceededEvent $event An event object encapsulating information about the successful command.
     * @return void
     * @throws \InvalidArgumentException on argument parsing errors.
     * @since 1.3.0
     */
    public function commandSucceeded(CommandSucceededEvent $event): void;
}
